const commandPattern = /^\/(trangthai)(?:@[A-Za-z0-9_]+)?(?:\s+.*)?$/i;

const text = (value) => (value == null ? '' : String(value));

function normalizeStatusUpdate(update) {
  const message = update?.message ?? update?.edited_message;
  const updateId = update?.update_id;
  if (updateId == null || !message?.chat?.id || !message?.from?.id) {
    throw new Error('Telegram update requires update_id, message.chat.id and message.from.id');
  }
  const commandText = text(message.text).trim();
  const isStatus = commandPattern.test(commandText);
  const stableId = text(updateId);
  return {
    envelope: {
      request_id: `tg-${stableId}`,
      operation_id: `tg-${stableId}`,
      event_type: 'TELEGRAM_UPDATE',
      actor_user_id: text(message.from.id),
      branch_id: null,
      business_date: null,
      config_version: null,
      payload: {
        command: commandText.split(/\s+/, 1)[0] || '',
        intent: isStatus ? 'READ_STATUS' : 'COMMAND_NOT_AVAILABLE',
      },
    },
    reply_target: {
      chat_id: text(message.chat.id),
      message_thread_id: message.message_thread_id == null ? null : text(message.message_thread_id),
    },
    command: isStatus ? '/trangthai' : commandText.split(/\s+/, 1)[0] || '',
  };
}


const update = $input.first()?.json ?? {};
return [{ json: normalizeStatusUpdate(update) }];

const MAX_MESSAGE_LENGTH = 4096;

const asText = (value) => (value == null ? '' : String(value));

function messageMap(tables, locale = 'vi-VN') {
  const map = new Map();
  for (const row of tables?.CONFIG_THONG_BAO ?? []) {
    if (asText(row.trang_thai).toUpperCase() === 'INACTIVE') continue;
    if (asText(row.locale) && asText(row.locale) !== locale) continue;
    map.set(asText(row.message_key), asText(row.message_text));
  }
  return map;
}

function render(template, values) {
  return asText(template).replace(/\{([a-z0-9_]+)\}/gi, (_match, key) => asText(values[key]));
}

function errorTemplateKey(errorCode) {
  if (errorCode === 'USER_NOT_ACTIVE') return 'USER_NOT_ACTIVE';
  if (errorCode === 'COMMAND_NOT_AVAILABLE') return 'COMMAND_NOT_AVAILABLE';
  return 'ERROR_GENERIC';
}

function formatStatus({ gatewayResult, tables, locale = 'vi-VN' } = {}) {
  const messages = messageMap(tables, locale);
  if (!gatewayResult?.ok) {
    const response = gatewayResult?.response ?? {};
    const template = messages.get(errorTemplateKey(response.error_code)) || messages.get('ERROR_GENERIC') || 'ERROR error_id={error_id}';
    return { text: render(template, { error_id: response.error_id || 'unknown' }).slice(0, MAX_MESSAGE_LENGTH) };
  }

  const response = gatewayResult.response;
  const lines = [
    render(messages.get('STATUS_HEADER'), response),
    render(messages.get('STATUS_CONFIG_LINE'), response),
    render(messages.get('STATUS_BRANCH_COUNT_LINE'), response),
  ];
  for (const branch of response.active_branches ?? []) {
    lines.push(render(messages.get('STATUS_BRANCH_LINE'), branch));
  }
  lines.push(render(messages.get('STATUS_MAINTENANCE_LINE'), response));
  return { text: lines.filter(Boolean).join('\n').slice(0, MAX_MESSAGE_LENGTH) };
}



const input = $input.first()?.json ?? {};
const normalized = $('Normalize Status Update').first()?.json ?? {};
const messages = $('Read CONFIG_THONG_BAO').all().map((item) => item.json);
const gatewayResult = input.gateway ?? input;
const result = formatStatus({ gatewayResult, tables: { CONFIG_THONG_BAO: messages } });
return [{ json: { reply_target: normalized.reply_target, text: result.text } }];

